def build(a):
    n = a["cols"] * a["rows"]
    rigid = RIGID.format(extra=a["extra"])
    body = a["body"].replace("{soft}", SOFT).replace("{rigid}", rigid)
    head = "ELITE SLIME: %s. Written 2026-11-10. %s\n\n%s\n\n%s\n\n" % (a["title"], a["intro"], a["what"], LESSONS)
    how = """HOW TO USE
- Attach ONE image: Animations/EliteSlime/reference_image.png (the accepted Elite look: grey stone, steel back-plate, leather belt, heater shield, floating stone fist with a sword, amber eyes, thin near-black outline, on magenta). Ask for a %s image, as large as it will give you (the earlier sheets came as 2528 x 1696 and 2752 x 1536 and were fine). Paste everything between the two lines of equals signs. Gemini again (its JPG is fine; do not re-save it in an editor).
- Generate several and keep the best. Save it in inbox/ (for example inbox/elite_slime_%s.jpg) and tell me. I cut it, check it and put it in the page.
- OPTIONAL second try if the creature drifts (a different slime, a changed shield or armour, the wrong size): also attach the idle sheet (Animations/EliteSlime/idle/source/elite_idle_sheet.jpg) and put this sentence first: 'The second image is only the SAME CREATURE at the same size on the same floor, to copy exactly. Draw the poses described below in a new sheet, not the idle breath, and make the creature SMALLER in its panels than in the second image.'
- What I check: %s
- Planned cut: %s
""" % (a["ratio"], a["tag"], a["check"], a["cut"])
    rep = REPLIES.format(specific=a["specific"]) + "\n\n"
    grid = "%d columns x %d rows, %s equal panels" % (a["cols"], a["rows"], {6: "six", 8: "eight"}[n])
    first = a["what"].split("WHAT IT IS. ", 1)[1].split(". ")[0] + "."
    prompt = """==============================================================================
OUTPUT: exactly ONE static image, a sprite sheet, and nothing else. Do NOT create a GIF, an animation, a video, a preview, extra images, alternate versions or a second attempt. No other files.

Create the sprite sheet: a grid of %s, read left to right, top row first, then the bottom row. %s Every panel is one still pose, drawn crisp and clean; the motion is in the DIFFERENCE between the panels, never drawn inside one.

%s

%s

%s

""" % (grid, first, CHARACTER, (VIEW + " " + a.get("view_extra", "")).strip(), body)
    prompt += BACKGROUND + "\n\nFINAL REMINDER: output ONE single static image only. No GIF, no extra images. " + a["final"] + "\n==============================================================================\n"
    return head + how + rep + prompt


if __name__ == "__main__":
    for a in ANIMS:
        d = os.path.join(ROOT, "Animations", "EliteSlime", a["folder"], "source")
